/** Sends the capture to the text recognition service and returns the recognized text. */
async function recognizeText(id) {
  const library = require("./library");
  const shot = library.get(id);
  if (!shot) throw new Error(`no capture ${id}`);
  const response = await fetch(OCR_ENDPOINT, {
    method: "POST",
    headers: { "content-type": "image/png" },
    body: fs.readFileSync(shot.file),
  });
  if (!response.ok) throw new Error(`recognition failed: ${response.status}`);
  return (await response.json()).text;
}

